#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_shatterPass;
float4 amzSample_shatterPass(float2 uv) { return float4(amzt_shatterPass.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_edgeMask;
float4 amzSample_edgeMask(float2 uv) { return float4(amzt_edgeMask.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
uniform shader amzt_hblur;
float4 amzSample_hblur(float2 uv) { return float4(amzt_hblur.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
uniform shader amzt_vblur;
float4 amzSample_vblur(float2 uv) { return float4(amzt_vblur.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_shatterPass(uv);if(tex==2) return amzSample_edgeMask(uv);if(tex==3) return amzSample_hblur(uv);if(tex==4) return amzSample_vblur(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_progress;
uniform float amzp_cellScale;
uniform float amzp_randomness;
uniform float amzp_scatter;
uniform float amzp_rotAmount;
uniform float amzp_gravity;
uniform float amzp_edgeWidth;
uniform float amzp_edgeFeather;
layout(color) uniform half4 amzp_edgeColor;
uniform float amzp_edgeGlow;
uniform float amzp_quality;
uniform float amzp_glowOnly;








    const float PI = 3.14159265358979323846;


    float hash11(float n){ return fract(sin(n)*43758.5453123); }
    float hash21(float2 p){ return fract(1e4*sin(17.0*p.x + 0.1*p.y)*(0.1+abs(sin(13.0*p.y+7.0*p.x)))); }


    float2x2 r2(float a){ float s=sin(a), c=cos(a); return float2x2(c,-s,s,c); }


    float4 voronoi(float2 uv, float amzp_cellScale, float randAmt){
      float2 g = uv * amzp_cellScale;
      float2 i = floor(g);
      float2 f = fract(g);

      float d1 = 1e9; float2 id1 = float2(0.0);
      float d2 = 1e9;

      for(int y=-1;y<=1;y++){
        for(int x=-1;x<=1;x++){
          float2 o = float2(x,y);
          float2 h = i + o;

          float s = hash21(h);
          float2 p = fract(float2(s, hash11(s*91.7)) + randAmt*0.6);
          float2 diff = (o + p) - f;
          float d = dot(diff,diff);
          if(d < d1){ d2 = d1; d1 = d; id1 = h + p; }
          else if(d < d2){ d2 = d; }
        }
      }
      return float4(d1, d2, id1);
    }


    float4 blurInternal(int tex, float2 texOffset, float2 st, float numBlurPixelsPerSide){
      float adjSigma = numBlurPixelsPerSide / 2.14596602;
      const float PIc = 3.14159265;
       float3 incG;
      incG.x = 1.0 / (sqrt(2.0 * PIc) * max(adjSigma,1e-4));
      incG.y = exp(-0.5 / (max(adjSigma,1e-4) * max(adjSigma,1e-4)));
      incG.z = incG.y * incG.y;
      float4 avg = amzTexture(tex,st) * incG.x; float sum = incG.x;
      for(float i=1.0;i<=128.0;i+=2.0){
        float o0=i, o1=i+1.0;
        incG.xy *= incG.yz; float w0 = incG.x;
        incG.xy *= incG.yz; float w1 = incG.x;
        float w = w0 + w1;
        float off = (o0*w0 + o1*w1) / max(w,1e-6);
        float2 o = texOffset * off;
        avg += amzTexture(tex, st - o) * w;
        avg += amzTexture(tex, st + o) * w;
        sum += 2.0*w;
        if(i>numBlurPixelsPerSide) break;
      }
      return avg / max(sum,1e-6);
    }

    void amzRender(){
      int Q = int(int(amzp_quality));
      float taps = (Q==1)? 6.0 : (Q==2? 10.0 : 14.0);

      if(amzPass==0){

        float2 uv = amzLayerNorm(); 

        uv.x *= layer.x/layer.y;


        float4 v = voronoi(uv, amzp_cellScale, amzp_randomness);
        float d1 = sqrt(v.x);
        float d2 = sqrt(v.y);
        float2 site = v.zw; 

        float2 siteUV = site / amzp_cellScale;


        float sid = hash21(floor(site));
        float2 dir = normalize(float2(cos(sid*6.2831), sin(sid*6.2831)) + 1e-3);
        float ang = radians(amzp_rotAmount) * amzp_progress * (sid*2.0-1.0);


        float2 grav = float2(0.0, amzp_gravity * amzp_progress * amzp_progress);
        float2 T = dir * amzp_scatter * amzp_progress + grav;


        float2 p = uv - siteUV;
        p = r2(-ang) * p; 
        p -= T;           
        float2 sampleUV = p + siteUV;


        sampleUV.x /= layer.x/layer.y;

        float4 src = amzTexture(0, (float4(sampleUV,0.,1.)*amzLayerToScreen()).xy);


        float e = clamp((d2 - d1) * amzp_cellScale * amzp_edgeWidth, 0.0, 1.0);
        float edgeMask = 1.0 - smoothstep(0.0, amzp_edgeFeather, e);

        amzOutput = float4(src.rgb, edgeMask * src.a);
        return;
      }

      if(amzPass==1){

        float4 s = amzTexture(1, amzScreenNorm());
        amzOutput = float4(s.a);
        return;
      }

      if(amzPass==2){

        float k = (Q==1? 6.0 : Q==2? 10.0 : 14.0);
        float kernelSize = k;
        float2 texOffset = float2(1.0/(screen.zw/2.0).x, 0.0);
        amzOutput = blurInternal(2, texOffset, amzScreenNorm().st, kernelSize);
        return;
      }

      if(amzPass==3){

        float k = (Q==1? 6.0 : Q==2? 10.0 : 14.0);
        float kernelSize = k;
        float2 texOffset = float2(0.0, 1.0/(screen.zw/2.0).y);
        amzOutput = blurInternal(3, texOffset, amzScreenNorm().st, kernelSize);
        return;
      }


      float4 shattered = amzTexture(1, amzScreenNorm());
      float3 baseRGB = shattered.rgb;
      float edgeB = amzTexture(4, amzScreenNorm()).r;
      float3 glowRGB = amzp_edgeColor.rgb * edgeB * amzp_edgeGlow * amzp_edgeColor.a;
      float3 outRGB = (amzp_glowOnly>0.5) ? glowRGB : (baseRGB + glowRGB);
      amzOutput = float4(outRGB, shattered.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

